// Translates the built `_headers` file (Cloudflare Pages syntax) into the configuration of the other targets:
// `vercel.json`, a Caddy site block, an Nginx server block and an Apache/LiteSpeed `.htaccess`.
// Every translator is a pure function of the parsed rules (parseHeadersFile from the landing report).
// Design: openspec/changes/add-deploy-adapters/design.md, Decision 3.
import { headersForPath, parseHeadersFile } from '../report/headers.mjs';

export { parseHeadersFile };

export const GENERATED_NOTE =
  'Generated by landing-factory (scripts/deploy/headers.mjs) from dist/_headers. Do not edit by hand.';

/** `x-content-type-options` to `X-Content-Type-Options`. */
export const canonicalName = (name) =>
  name
    .split('-')
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('-');

const isGlobal = (pattern) => pattern === '/*';
const hasPlaceholder = (pattern) => /:[A-Za-z]/.test(pattern);

/** A path that the pattern matches, to ask which headers apply there. */
const samplePath = (pattern) =>
  pattern.replace(/\*/g, 'x').replace(/:[A-Za-z]\w*/g, 'x');

/** The pattern as a regular expression source over the path without its leading slash. */
function patternRegex(pattern) {
  const body = pattern.replace(/^\//, '');
  const source = body
    .split(/(\*|:[A-Za-z]\w*)/)
    .map((part) =>
      part === '*'
        ? '.*'
        : /^:[A-Za-z]/.test(part)
          ? '[^/]+'
          : part.replace(/[.+?^${}()|[\]\\]/g, '\\$&'),
    )
    .join('');
  return `^${source}$`;
}

/** Rules in file order, with detach lines kept for the targets that can use them. */
const setHeaders = (rule) => rule.headers.filter((h) => !h.detach);

const quote = (value, label) => {
  if (/[\r\n]/.test(value))
    throw new Error(`${label}: a header value must not contain a line break`);
  return `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
};

/** Every distinct (name, value) pair of the rules, in order. */
export function allHeaders(rules) {
  const seen = new Set();
  const out = [];
  for (const rule of rules)
    for (const header of setHeaders(rule)) {
      const key = `${header.name}\u0000${header.value}`;
      if (seen.has(key)) continue;
      seen.add(key);
      out.push(header);
    }
  return out;
}

// --- Vercel -----------------------------------------------------------------

/** `/_astro/*` to `/_astro/(.*)`: Vercel `source` patterns use path-to-regexp. */
const vercelSource = (pattern) =>
  isGlobal(pattern) ? '/(.*)' : pattern.replace(/\*/g, '(.*)');

/**
 * `vercel.json` as an object. Hashed assets keep their year-long caching, every header of every rule is
 * kept, directory URLs have a trailing slash (what Astro writes) and Vercel serves `404.html` by itself.
 */
export function toVercelJson(rules) {
  return {
    cleanUrls: false,
    trailingSlash: true,
    headers: rules
      .filter((rule) => setHeaders(rule).length)
      .map((rule) => ({
        source: vercelSource(rule.pattern),
        headers: setHeaders(rule).map((h) => ({
          key: canonicalName(h.name),
          value: h.value,
        })),
      })),
  };
}

// --- Caddy ------------------------------------------------------------------

/**
 * A Caddy site block. `site` is the host name and `root` the folder to serve (`.../current`).
 * Rules with a path matcher use `header @ruleN`; `:name` placeholders become a `path_regexp` matcher.
 */
export function toCaddy(
  rules,
  { site = 'example.com', root = '/var/www/site/current' } = {},
) {
  const lines = [
    `# ${GENERATED_NOTE}`,
    `${site} {`,
    `\troot * ${root}`,
    '\tencode zstd gzip',
  ];
  const matchers = [];
  const blocks = [];
  rules.forEach((rule, index) => {
    const set = setHeaders(rule);
    const detach = rule.headers.filter((h) => h.detach);
    if (!set.length && !detach.length) return;
    let target = '';
    if (!isGlobal(rule.pattern)) {
      const name = `@rule${index + 1}`;
      matchers.push(
        hasPlaceholder(rule.pattern)
          ? `\t${name} path_regexp ${patternRegex(rule.pattern).replace('^', '^/')}`
          : `\t${name} path ${rule.pattern}`,
      );
      target = ` ${name}`;
    }
    blocks.push(`\theader${target} {`);
    for (const h of set)
      blocks.push(`\t\t${canonicalName(h.name)} ${quote(h.value, 'caddy')}`);
    for (const h of detach) blocks.push(`\t\t-${canonicalName(h.name)}`);
    blocks.push('\t}');
  });
  lines.push(...matchers, ...blocks);
  lines.push(
    '\thandle_errors {',
    '\t\trewrite * /404.html',
    '\t\tfile_server',
    '\t}',
    '\tfile_server',
    '}',
    '',
  );
  return lines.join('\n');
}

// --- Nginx ------------------------------------------------------------------

const nginxValue = (value) => {
  if (/[\r\n$]/.test(value))
    throw new Error(
      'nginx: a header value must not contain a line break or "$"',
    );
  return quote(value, 'nginx');
};

function nginxLocation(pattern) {
  if (!pattern.includes('*') && !hasPlaceholder(pattern)) return `= ${pattern}`;
  if (/^[^*:]*\/\*$/.test(pattern)) return `^~ ${pattern.slice(0, -1)}`;
  return `~ ${patternRegex(pattern).replace('^', '^/')}`;
}

/**
 * An Nginx server block for the HTTP side; Certbot adds the TLS directives. `add_header` in a location
 * replaces the ones of the server level, so each location repeats the headers that apply to its paths.
 */
export function toNginx(
  rules,
  { site = 'example.com', root = '/var/www/site/current' } = {},
) {
  const emit = (headers, indent) =>
    Object.entries(headers).map(
      ([name, value]) =>
        `${indent}add_header ${canonicalName(name)} ${nginxValue(value)} always;`,
    );
  const globalHeaders = headersForPath(rules, '/');
  const lines = [
    `# ${GENERATED_NOTE}`,
    'server {',
    '    listen 80;',
    '    listen [::]:80;',
    `    server_name ${site};`,
    `    root ${root};`,
    '    index index.html;',
    '    server_tokens off;',
    '    gzip on;',
    '    gzip_types text/css application/javascript application/json image/svg+xml;',
    '',
    '    # Certbot (certbot --nginx) adds the 443 listener and the redirect from HTTP to HTTPS.',
    ...emit(globalHeaders, '    '),
    '',
    '    location / {',
    ...emit(globalHeaders, '        '),
    '        try_files $uri $uri/ =404;',
    '    }',
  ];
  for (const rule of rules) {
    if (isGlobal(rule.pattern) || !setHeaders(rule).length) continue;
    const effective = headersForPath(rules, samplePath(rule.pattern));
    lines.push(
      '',
      `    location ${nginxLocation(rule.pattern)} {`,
      ...emit(effective, '        '),
      '        try_files $uri $uri/ =404;',
      '    }',
    );
  }
  lines.push(
    '',
    '    error_page 404 /404.html;',
    '    location = /404.html {',
    '        internal;',
    ...emit(globalHeaders, '        '),
    '    }',
    '}',
    '',
  );
  return lines.join('\n');
}

// --- .htaccess (Apache and LiteSpeed) ----------------------------------------

/**
 * `.htaccess` for shared hosting: no directory listings, `404.html`, HTTP to HTTPS, and the headers with
 * `Header always set`. Rules that do not cover every path set an environment variable in mod_rewrite and the
 * header is conditional on it (`env=`), which Apache and LiteSpeed both support.
 */
export function toHtaccess(rules) {
  const lines = [
    `# ${GENERATED_NOTE}`,
    'Options -Indexes',
    'ErrorDocument 404 /404.html',
    '',
    '<IfModule mod_rewrite.c>',
    'RewriteEngine On',
    'RewriteCond %{HTTPS} off',
    'RewriteCond %{HTTP:X-Forwarded-Proto} !https',
    'RewriteRule ^ https://%{HTTP_HOST}%{REQUEST_URI} [L,R=301]',
  ];
  const conditional = rules.filter(
    (rule) =>
      !isGlobal(rule.pattern) &&
      (setHeaders(rule).length || rule.headers.length),
  );
  conditional.forEach((rule, i) =>
    lines.push(
      `RewriteRule ${patternRegex(rule.pattern)} - [E=LF_RULE${i + 1}:1]`,
    ),
  );
  lines.push('</IfModule>', '', '<IfModule mod_headers.c>');
  for (const rule of rules.filter((r) => isGlobal(r.pattern)))
    lines.push(...htaccessHeaders(rule, ''));
  conditional.forEach((rule, i) =>
    lines.push(...htaccessHeaders(rule, ` env=LF_RULE${i + 1}`)),
  );
  lines.push('</IfModule>', '');
  return lines.join('\n');
}

function htaccessHeaders(rule, suffix) {
  const out = [`# ${rule.pattern}`];
  for (const h of rule.headers)
    out.push(
      h.detach
        ? `Header always unset ${canonicalName(h.name)}${suffix}`
        : `Header always set ${canonicalName(h.name)} ${quote(h.value, 'htaccess')}${suffix}`,
    );
  return out;
}

// --- One entry point -----------------------------------------------------------

/** The generated files of a target: { 'vercel.json': text } or { 'caddy.conf', 'nginx.conf' } or { '.htaccess' }. */
export function generateHeaderConfig(target, rules, options = {}) {
  if (target === 'vercel')
    return {
      'vercel.json': `${JSON.stringify(toVercelJson(rules), null, 2)}\n`,
    };
  if (target === 'vps')
    return {
      'Caddyfile.snippet': toCaddy(rules, options),
      'nginx.conf.snippet': toNginx(rules, options),
    };
  if (target === 'shared') return { '.htaccess': toHtaccess(rules) };
  return {};
}
